<?php $labels=['pending_payment'=>'Chờ thanh toán online','pending_hotel_payment'=>'Chờ thanh toán tại quầy','confirmed'=>'Đã xác nhận','checked_in'=>'Đã nhận phòng','completed'=>'Hoàn tất','cancelled'=>'Đã hủy'];$paid=$booking['payment_status']==='paid'||(int)$booking['has_success_payment']===1; ?>
