<?php foreach(['success'=>'alert-success','error'=>'alert-error'] as $k=>$c):if(!empty($_SESSION['flash_'.$k])): ?><div class="<?= $c ?>"><?= htmlspecialchars($_SESSION['flash_'.$k],ENT_QUOTES,'UTF-8') ?></div><?php unset($_SESSION['flash_'.$k]);endif;endforeach; ?>
