<section class="panel detail-panel"><div class="panel-heading"><div><span class="eyebrow">RESERVATION</span><h2>Thông tin đặt phòng</h2></div><span class="status status-<?= htmlspecialchars($booking['booking_status'],ENT_QUOTES,'UTF-8') ?>"><?= $labels[$booking['booking_status']]??$booking['booking_status'] ?></span></div><div class="detail-grid">
<?php foreach(['guest_name'=>'Khách hàng','guest_email'=>'Email','guest_phone'=>'Số điện thoại','hotel_name'=>'Khách sạn'] as $k=>$v): ?><div><small><?= $v ?></small><strong><?= htmlspecialchars((string)($booking[$k]??'—'),ENT_QUOTES,'UTF-8') ?></strong></div><?php endforeach; ?>
<div><small>Ngày nhận phòng</small><strong><?= date('d/m/Y',strtotime($booking['check_in'])) ?></strong></div><div><small>Ngày trả phòng</small><strong><?= date('d/m/Y',strtotime($booking['check_out'])) ?></strong></div><div><small>Số đêm</small><strong><?= (int)$booking['number_of_nights'] ?> đêm</strong></div><div><small>Số khách</small><strong><?= (int)$booking['total_guests'] ?> khách</strong></div></div><?php if($booking['special_request']): ?><p class="request-note"><?= nl2br(htmlspecialchars($booking['special_request'],ENT_QUOTES,'UTF-8')) ?></p><?php endif; ?></section>
<section class="panel detail-panel"><div class="panel-heading"><div><span class="eyebrow">ROOMS</span><h2>Phòng trong đơn</h2></div></div><?php if(!$booking['rooms']): ?><p class="muted">Chưa có dữ liệu phòng chi tiết.</p><?php else: ?><div class="table-wrap"><table><thead><tr><th>LOẠI PHÒNG</th><th>SỐ PHÒNG</th><th>SL</th><th>ĐƠN GIÁ / ĐÊM</th><th>TẠM TÍNH</th></tr></thead><tbody><?php foreach($booking['rooms'] as $r): ?><tr><td><?= htmlspecialchars($r['room_name_snapshot']?:($r['room_type_name']??'Phòng'),ENT_QUOTES,'UTF-8') ?></td><td><?= htmlspecialchars($r['room_number_snapshot']?:($r['room_number']??'—'),ENT_QUOTES,'UTF-8') ?></td><td><?= (int)$r['quantity'] ?></td><td><?= number_format((float)$r['price_per_night'],0,',','.') ?> ₫</td><td class="amount"><?= number_format((float)$r['subtotal'],0,',','.') ?> ₫</td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?><div class="money-summary"><?php foreach(['subtotal'=>'Tạm tính','discount_amount'=>'Giảm giá','service_amount'=>'Dịch vụ','total_amount'=>'Tổng thanh toán'] as $k=>$v): ?><div class="<?= $k==='total_amount'?'grand-total':'' ?>"><span><?= $v ?></span><strong><?= number_format((float)$booking[$k],0,',','.') ?> ₫</strong></div><?php endforeach; ?></div></section>
<section class="panel detail-panel"><div class="panel-heading"><div><span class="eyebrow">PAYMENT HISTORY</span><h2>Lịch sử thanh toán</h2></div></div><?php if(!$booking['payments']): ?><p class="muted">Chưa có giao dịch thanh toán được ghi nhận.</p><?php else: ?><div class="table-wrap"><table><thead><tr><th>PHƯƠNG THỨC</th><th>MÃ GIAO DỊCH</th><th>SỐ TIỀN</th><th>TRẠNG THÁI</th><th>THỜI GIAN</th></tr></thead><tbody><?php foreach($booking['payments'] as $p): ?><tr><td><?= $p['payment_method']==='online'?'Online':'Tại quầy' ?></td><td><?= htmlspecialchars($p['transaction_code']?:'—',ENT_QUOTES,'UTF-8') ?></td><td><?= number_format((float)$p['amount'],0,',','.') ?> ₫</td><td><?= htmlspecialchars($p['payment_status'],ENT_QUOTES,'UTF-8') ?></td><td><?= $p['paid_at']?date('d/m/Y H:i',strtotime($p['paid_at'])):date('d/m/Y H:i',strtotime($p['created_at'])) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
</div><aside class="booking-detail-side"><section class="panel workflow-panel"><span class="eyebrow">WORKFLOW</span><h2>Xử lý đơn đặt phòng</h2><p class="muted">Thao tác phụ thuộc phương thức thanh toán và trạng thái hiện tại.</p>
<?php if($booking['booking_status']==='pending_payment'&&$booking['payment_method']==='online'): ?><?php if($paid): ?><div class="workflow-hint hint-good">Thanh toán online đã thành công. Có thể xác nhận đơn.</div><?php else: ?><div class="workflow-hint hint-warn">Chưa ghi nhận thanh toán online thành công. Chưa thể xác nhận.</div><?php endif; ?><?php if($paid): ?><form method="post" action="<?= BASE_URL ?>/admin/bookings/update" onsubmit="return confirm('Xác nhận đơn đã thanh toán online?')"><input type="hidden" name="_csrf" value="<?= htmlspecialchars(Csrf::token(),ENT_QUOTES,'UTF-8') ?>"><input type="hidden" name="booking_id" value="<?= (int)$booking['id'] ?>"><input type="hidden" name="action" value="confirm_online"><button class="btn-primary workflow-button">Xác nhận đặt phòng</button></form><?php endif; ?>
<?php elseif($booking['booking_status']==='pending_hotel_payment'&&$booking['payment_method']==='pay_at_hotel'): ?><div class="workflow-hint hint-warn">Chỉ xác nhận sau khi khách đến quầy và nhân viên đã thu đủ tiền.</div><form method="post" action="<?= BASE_URL ?>/admin/bookings/update" onsubmit="return confirm('Xác nhận khách đã đến quầy và thanh toán đủ?')"><input type="hidden" name="_csrf" value="<?= htmlspecialchars(Csrf::token(),ENT_QUOTES,'UTF-8') ?>"><input type="hidden" name="booking_id" value="<?= (int)$booking['id'] ?>"><input type="hidden" name="action" value="confirm_hotel_payment"><button class="btn-primary workflow-button">Xác nhận đã thu tiền tại quầy</button></form>
<?php elseif($booking['booking_status']==='confirmed'): ?><div class="workflow-hint hint-good">Đơn đã xác nhận, sẵn sàng nhận phòng.</div><form method="post" action="<?= BASE_URL ?>/admin/bookings/update"><input type="hidden" name="_csrf" value="<?= htmlspecialchars(Csrf::token(),ENT_QUOTES,'UTF-8') ?>"><input type="hidden" name="booking_id" value="<?= (int)$booking['id'] ?>"><input type="hidden" name="action" value="check_in"><button class="btn-primary workflow-button">Xác nhận nhận phòng</button></form>
<?php elseif($booking['booking_status']==='checked_in'): ?><div class="workflow-hint hint-good">Khách đang lưu trú tại khách sạn.</div><form method="post" action="<?= BASE_URL ?>/admin/bookings/update"><input type="hidden" name="_csrf" value="<?= htmlspecialchars(Csrf::token(),ENT_QUOTES,'UTF-8') ?>"><input type="hidden" name="booking_id" value="<?= (int)$booking['id'] ?>"><input type="hidden" name="action" value="complete"><button class="btn-primary workflow-button">Hoàn tất trả phòng</button></form><?php else: ?><div class="workflow-hint">Đơn đã kết thúc hoặc không có thao tác tiếp theo.</div><?php endif; ?>
<?php if(in_array($booking['booking_status'],['pending_payment','pending_hotel_payment','confirmed'],true)): ?><form method="post" action="<?= BASE_URL ?>/admin/bookings/update" onsubmit="return confirm('Bạn chắc chắn muốn hủy đơn?')"><input type="hidden" name="_csrf" value="<?= htmlspecialchars(Csrf::token(),ENT_QUOTES,'UTF-8') ?>"><input type="hidden" name="booking_id" value="<?= (int)$booking['id'] ?>"><input type="hidden" name="action" value="cancel"><button class="btn-danger workflow-button">Hủy đơn đặt phòng</button></form><?php endif; ?></section>
<section class="panel payment-summary-panel"><span class="eyebrow">PAYMENT SUMMARY</span><h2>Thông tin thanh toán</h2><div class="side-info"><small>Phương thức</small><strong><?= $booking['payment_method']==='online'?'Thanh toán online':'Thanh toán tại khách sạn' ?></strong></div><div class="side-info"><small>Trạng thái</small><strong><?= $paid?'Đã thanh toán':'Chưa thanh toán' ?></strong></div><div class="side-info"><small>Ngày tạo đơn</small><strong><?= date('d/m/Y H:i',strtotime($booking['created_at'])) ?></strong></div><?php if($booking['confirmer_name']): ?><div class="side-info"><small>Người xác nhận</small><strong><?= htmlspecialchars($booking['confirmer_name'],ENT_QUOTES,'UTF-8') ?></strong></div><?php endif; ?></section></aside></div>
